//! Isolated NEP-141 settlement. One immutable token allowlist per deployment.
#[path="../../shared/model.rs"]mod model;pub use model::FeatureId;use model::*;
use near_sdk::{near,env,ext_contract,AccountId,NearToken,Gas,Promise,PromiseError,PanicOnDefault};use near_sdk::json_types::{U128,U64};use near_sdk::store::LookupMap;
#[near(serializers=[borsh,json])]
#[derive(Clone)]pub struct Sku{pub feature:FeatureId,pub developer:AccountId,pub source_terms_hash:String,pub artifact:String,pub price:U128,pub bps:u16,pub cap:U128,pub paid:U128,pub sold:U64,pub verified:bool,pub accepted:bool,pub paused:bool,pub terms_hash:String,pub storage_available:U128,pub use_escrow:U128}
#[near(serializers=[borsh,json])]
#[derive(Clone,Default)]pub struct Ledger{pub claimable:U128,pub pending:U128,pub withdrawn:U128,pub nonce:U64}
#[near(serializers=[borsh,json])]
#[derive(Clone)]pub struct Order{pub buyer:AccountId,pub feature:FeatureId,pub token:AccountId,pub amount:U128,pub developer_share:U128,pub merchant_share:U128,pub artifact_sha256:String,pub terms_hash:String}
#[near(serializers=[json])]
#[serde(deny_unknown_fields)]pub struct PurchaseMsg{pub feature:FeatureId,pub order_id:String}
#[near(contract_state)]
#[derive(PanicOnDefault)]pub struct TokenMarket{marketplace:AccountId,token:AccountId,decimals:u8,symbol:String,skus:LookupMap<FeatureId,Sku>,ledgers:LookupMap<AccountId,Ledger>,orders:LookupMap<(AccountId,String),Order>,credits:LookupMap<(AccountId,FeatureId),u64>,actions:LookupMap<(AccountId,String),FeatureId>,bootstrap:u128,storage_funded:u128,sales:u128,claimable:u128,pending:u128,withdrawn:u128}
#[ext_contract(ext_market)]#[allow(dead_code)]trait Source{fn get_release(&self,feature:FeatureId)->Option<model::SourceRelease>;}
#[ext_contract(ext_ft)]#[allow(dead_code)]trait Ft{fn ft_transfer(&mut self,receiver_id:AccountId,amount:U128,memo:Option<String>);}
#[ext_contract(ext_self)]#[allow(dead_code)]trait Callbacks{fn on_import(&mut self,feature:FeatureId)->bool;fn on_withdraw(&mut self,account_id:AccountId,nonce:U64)->bool;}
#[near]
impl TokenMarket{
 #[init]pub fn new(marketplace:AccountId,token:AccountId,decimals:u8,symbol:String)->Self{assert!(!env::state_exists(),"ALREADY_INITIALIZED");assert!(decimals<=24&&symbol.len()<=16&&!symbol.is_empty()&&symbol.bytes().all(|c|c.is_ascii_alphanumeric()||c==b'-'),"INVALID_TOKEN_METADATA");assert_ne!(token,env::current_account_id(),"TOKEN_SELF");let bootstrap=cost(env::storage_usage()+4096);assert!(env::account_balance().as_yoctonear()>=bootstrap,"BOOTSTRAP_UNFUNDED");Self{marketplace,token,decimals,symbol,skus:LookupMap::new(b"s"),ledgers:LookupMap::new(b"l"),orders:LookupMap::new(b"o"),credits:LookupMap::new(b"c"),actions:LookupMap::new(b"a"),bootstrap,storage_funded:0,sales:0,claimable:0,pending:0,withdrawn:0}}
 #[payable]pub fn import_release(&mut self,feature:FeatureId,developer:AccountId,source_terms_hash:String,artifact_sha256:String,price:U128,bps:u16,cap:U128)->Promise{
 feature.validate();digest(&source_terms_hash);digest(&artifact_sha256);assert_eq!(feature.owner,env::predecessor_account_id(),"NOT_MERCHANT");assert!(price.0>0&&bps<=10000,"INVALID_TERMS");assert!(!self.skus.contains_key(&feature),"DUPLICATE_SKU");let deposit=env::attached_deposit().as_yoctonear();assert!(deposit>=cost(12288),"STORAGE_UNFUNDED");self.check_native(add(self.storage_funded,deposit));let hash=hex(&env::sha256(&near_sdk::borsh::to_vec(&(env::current_account_id(),self.token.clone(),self.decimals,feature.clone(),developer.clone(),source_terms_hash.clone(),artifact_sha256.clone(),price,bps,cap)).unwrap()));self.flush();let before=env::storage_usage();self.storage_funded=add(self.storage_funded,deposit);if !self.ledgers.contains_key(&feature.owner){self.ledgers.insert(feature.owner.clone(),Ledger::default());}if !self.ledgers.contains_key(&developer){self.ledgers.insert(developer.clone(),Ledger::default());}self.skus.insert(feature.clone(),Sku{feature:feature.clone(),developer,source_terms_hash,artifact:artifact_sha256,price,bps,cap,paid:U128(0),sold:U64(0),verified:false,accepted:false,paused:false,terms_hash:hash,storage_available:U128(deposit),use_escrow:U128(0)});self.charge(&feature,before,12288);ext_market::ext(self.marketplace.clone()).with_static_gas(Gas::from_tgas(15)).get_release(feature.clone()).then(ext_self::ext(env::current_account_id()).with_static_gas(Gas::from_tgas(25)).on_import(feature))
 }
 #[private]pub fn on_import(&mut self,feature:FeatureId)->bool{private();let mut f=self.skus.get(&feature).expect("UNKNOWN_SKU").clone();assert!(!f.verified&&!f.accepted,"IMPORT_ALREADY_VERIFIED");let ok=env::promise_result_checked(0,4096).ok().and_then(|b|source(&b,&f.feature,&f.developer,&f.source_terms_hash)).as_deref()==Some(f.artifact.as_str());f.verified=ok;self.skus.insert(feature.clone(),f);self.flush();event("token_release_checked",(feature,ok));ok}
 pub fn retry_import(&mut self,feature:FeatureId)->Promise{let f=self.skus.get(&feature).expect("UNKNOWN_SKU");assert_eq!(env::predecessor_account_id(),feature.owner,"NOT_MERCHANT");assert!(!f.verified&&!f.accepted,"ALREADY_VERIFIED");ext_market::ext(self.marketplace.clone()).with_static_gas(Gas::from_tgas(15)).get_release(feature.clone()).then(ext_self::ext(env::current_account_id()).with_static_gas(Gas::from_tgas(25)).on_import(feature))}
 pub fn accept_token_terms(&mut self,feature:FeatureId,expected_terms_hash:String){let f=self.skus.get_mut(&feature).expect("UNKNOWN_SKU");assert!(f.verified&&!f.accepted,"NOT_OPEN");assert_eq!(env::predecessor_account_id(),f.developer,"NOT_DEVELOPER");assert_eq!(f.terms_hash,expected_terms_hash,"TERMS_MISMATCH");f.accepted=true;self.flush();event("token_terms_accepted",feature);}
 pub fn set_paused(&mut self,feature:FeatureId,paused:bool){assert_eq!(env::predecessor_account_id(),feature.owner,"NOT_MERCHANT");self.skus.get_mut(&feature).expect("UNKNOWN_SKU").paused=paused;self.flush();}
 #[payable]pub fn fund_storage(&mut self,feature:FeatureId){assert_eq!(env::predecessor_account_id(),feature.owner,"NOT_MERCHANT");let amount=env::attached_deposit().as_yoctonear();assert!(amount>0,"INVALID_AMOUNT");self.check_native(add(self.storage_funded,amount));let f=self.skus.get_mut(&feature).expect("UNKNOWN_SKU");f.storage_available.0=add(f.storage_available.0,amount);self.storage_funded=add(self.storage_funded,amount);self.flush();}
 /// Must return the exact unused amount. No promise or asynchronous credit issuance.
 pub fn ft_on_transfer(&mut self,sender_id:AccountId,amount:U128,msg:String)->U128{
 assert_eq!(env::predecessor_account_id(),self.token,"TOKEN_NOT_ALLOWED");assert_eq!(env::attached_deposit().as_yoctonear(),0,"NO_NATIVE_PAYMENT");if msg.len()>1024||amount.0==0{return amount;}let input=match near_sdk::serde_json::from_str::<PurchaseMsg>(&msg){Ok(v)=>v,Err(_)=>return amount};let feature=input.feature;if !valid_feature(&feature)||!valid_id(&input.order_id){return amount;}let mut f=match self.skus.get(&feature){Some(v)=>v.clone(),None=>return amount};let order_key=(sender_id.clone(),input.order_id);if !f.verified||!f.accepted||f.paused||f.price!=amount||self.orders.contains_key(&order_key)||f.storage_available.0<cost(12288){return amount;}
 let royalty=split(amount.0,f.bps).min(f.cap.0-f.paid.0);let owner_share=amount.0-royalty;let credits=self.credits.get(&(sender_id.clone(),feature.clone())).copied().unwrap_or(0).checked_add(1).expect("OVERFLOW");let sold=f.sold.0.checked_add(1).expect("OVERFLOW");let claimable=add(self.claimable,amount.0);let sales=add(self.sales,amount.0);let dev=add(self.ledgers.get(&f.developer).unwrap().claimable.0,royalty);let merchant=add(self.ledgers.get(&feature.owner).unwrap().claimable.0,if f.developer==feature.owner{amount.0}else{owner_share});self.check_native(self.storage_funded);self.flush();let before=env::storage_usage();f.storage_available.0-=cost(4096);f.use_escrow.0=add(f.use_escrow.0,cost(4096));f.paid.0=add(f.paid.0,royalty);f.sold=U64(sold);self.ledgers.get_mut(&f.developer).unwrap().claimable=U128(dev);self.ledgers.get_mut(&feature.owner).unwrap().claimable=U128(merchant);self.claimable=claimable;self.sales=sales;let order=Order{buyer:sender_id.clone(),feature:feature.clone(),token:self.token.clone(),amount,developer_share:U128(royalty),merchant_share:U128(owner_share),artifact_sha256:f.artifact.clone(),terms_hash:f.terms_hash.clone()};self.skus.insert(feature.clone(),f);self.orders.insert(order_key.clone(),order.clone());self.credits.insert((sender_id,feature.clone()),credits);self.charge(&feature,before,8192);event("token_purchase",(order_key,order));U128(0)
 }
 pub fn consume_use(&mut self,feature:FeatureId,action_id:String)->U64{id(&action_id);let buyer=env::predecessor_account_id();let key=(buyer.clone(),action_id);assert!(!self.actions.contains_key(&key),"ACTION_REPLAY");let ck=(buyer,feature.clone());let count=self.credits.get(&ck).copied().unwrap_or(0);assert!(count>0,"NO_PAID_USE");let f=self.skus.get(&feature).expect("UNKNOWN_SKU");assert!(f.use_escrow.0>=cost(4096),"USE_ESCROW_BROKEN");self.flush();let before=env::storage_usage();let f=self.skus.get_mut(&feature).unwrap();f.use_escrow.0-=cost(4096);f.storage_available.0=add(f.storage_available.0,cost(4096));self.actions.insert(key.clone(),feature.clone());self.credits.insert(ck,count-1);self.charge(&feature,before,4096);event("token_use",(key,feature));U64(count-1)}
 #[payable]pub fn withdraw_tokens(&mut self,amount:U128)->Promise{assert_eq!(env::attached_deposit().as_yoctonear(),1,"ONE_YOCTO_REQUIRED");self.check_native(self.storage_funded);let who=env::predecessor_account_id();let mut l=self.ledgers.get(&who).expect("UNKNOWN_LEDGER").clone();assert!(amount.0>0&&amount.0<=l.claimable.0,"INVALID_AMOUNT");assert_eq!(l.pending.0,0,"PAYOUT_PENDING");l.nonce.0=l.nonce.0.checked_add(1).expect("OVERFLOW");l.pending=amount;l.claimable.0-=amount.0;let nonce=l.nonce;self.claimable-=amount.0;self.pending=add(self.pending,amount.0);self.ledgers.insert(who.clone(),l);self.flush();ext_ft::ext(self.token.clone()).with_attached_deposit(NearToken::from_yoctonear(1)).with_static_gas(Gas::from_tgas(25)).ft_transfer(who.clone(),amount,None).then(ext_self::ext(env::current_account_id()).with_static_gas(Gas::from_tgas(20)).on_withdraw(who,nonce))}
 #[private]pub fn on_withdraw(&mut self,account_id:AccountId,nonce:U64)->bool{private();let mut l=self.ledgers.get(&account_id).expect("UNKNOWN_LEDGER").clone();assert!(l.pending.0>0&&l.nonce==nonce,"STALE_PAYOUT");let ok=match env::promise_result_checked(0,4){Ok(v) if v.is_empty()||v==b"null"=>true,Err(PromiseError::Failed)=>false,_=>panic!("TOKEN_RESULT_UNKNOWN_KEEP_PENDING")};self.pending-=l.pending.0;if ok{self.withdrawn=add(self.withdrawn,l.pending.0);l.withdrawn.0=add(l.withdrawn.0,l.pending.0);}else{self.claimable=add(self.claimable,l.pending.0);l.claimable.0=add(l.claimable.0,l.pending.0);}l.pending=U128(0);self.ledgers.insert(account_id.clone(),l);self.flush();event("token_payout",(account_id,nonce,ok));ok}
 pub fn get_sku(&self,feature:FeatureId)->Option<Sku>{self.skus.get(&feature).cloned()}
 pub fn config(&self)->near_sdk::serde_json::Value{near_sdk::serde_json::json!({"contract_version":"earnpatch-token-market-v1","marketplace":self.marketplace,"token":self.token,"decimals":self.decimals,"symbol":self.symbol,"availability":"independent_token_sku_pause_control"})}
 pub fn get_order(&self,buyer:AccountId,order_id:String)->Option<Order>{self.orders.get(&(buyer,order_id)).cloned()}
 pub fn get_credits(&self,buyer:AccountId,feature:FeatureId)->U64{U64(self.credits.get(&(buyer,feature)).copied().unwrap_or(0))}
 pub fn get_action(&self,buyer:AccountId,action_id:String)->Option<FeatureId>{self.actions.get(&(buyer,action_id)).cloned()}
 pub fn get_payout(&self,account_id:AccountId)->Ledger{self.ledgers.get(&account_id).cloned().unwrap_or_default()}
 pub fn accounting(&self)->near_sdk::serde_json::Value{near_sdk::serde_json::json!({"token":self.token,"symbol":self.symbol,"decimals":self.decimals,"sales":U128(self.sales),"claimable":U128(self.claimable),"pending":U128(self.pending),"withdrawn":U128(self.withdrawn),"conserved":self.sales==self.claimable+self.pending+self.withdrawn,"native_storage_funded":U128(self.storage_funded),"native_backed":env::account_balance().as_yoctonear()>=add(self.bootstrap,self.storage_funded),"token_balance_note":"Liabilities are internal accounting; independently query ft_balance_of and in-flight receipts."})}
}
impl TokenMarket{fn flush(&mut self){self.skus.flush();self.ledgers.flush();self.orders.flush();self.credits.flush();self.actions.flush();}fn check_native(&self,storage:u128){assert!(env::account_balance().as_yoctonear()>=add(self.bootstrap,storage),"NATIVE_STORAGE_INSOLVENT");}fn charge(&mut self,k:&FeatureId,before:u64,bound:u64){self.flush();let delta=env::storage_usage().checked_sub(before).expect("UNEXPECTED_SHRINK");assert!(delta<=bound,"STORAGE_BOUND");let f=self.skus.get_mut(k).unwrap();f.storage_available.0=f.storage_available.0.checked_sub(cost(delta)).expect("STORAGE_UNFUNDED");self.flush();}}
fn hex(bytes:&[u8])->String{bytes.iter().map(|b|format!("{b:02x}")).collect()}
fn valid_id(s:&str)->bool{!s.is_empty()&&s.len()<=64&&s.bytes().all(|b|b.is_ascii_alphanumeric()||b==b'-'||b==b'_')}
fn valid_feature(f:&FeatureId)->bool{valid_id(&f.product)&&valid_id(&f.feature)&&f.version>0}
fn split(price:u128,bps:u16)->u128{price/10000*bps as u128+(price%10000)*bps as u128/10000}
